import { useState } from "react";
import "@/App.css";
// Cambiamos BrowserRouter por HashRouter
import { HashRouter, Routes, Route } from "react-router-dom"; 
import Home from "./pages/Home";
import Camera from "./pages/Camera";
import Gallery from "./pages/Gallery";
import History from "./pages/History";
import Result from "./pages/Result";

function App() {
  const [classificationResult, setClassificationResult] = useState(null);
  const [capturedImage, setCapturedImage] = useState(null);

  return (
    <div className="App">
      {/* 
        Cambiamos a HashRouter. Al usar hashes, ya no hace falta la propiedad 'basename' 
        porque el servidor siempre va a cargar el index de /pet-classifier y React 
        se va a encargar de leer la ruta que quede detrás del '#'
      */}
      <HashRouter>
        <Routes>
          <Route path="/" element={<Home />} />
          
          {/* Mapeamos los nombres de las funciones exactamente como los espera CameraPage */}
          <Route 
            path="/camera" 
            element={
              <Camera 
                setCapturedImage={setCapturedImage} 
                setClassificationResult={setClassificationResult} 
              />
            } 
          />
          
          {/* Hacemos lo mismo para Gallery por si usa la misma estructura de estados directos */}
          <Route 
            path="/gallery" 
            element={
              <Gallery 
                setCapturedImage={setCapturedImage} 
                setClassificationResult={setClassificationResult} 
              />
            } 
          />
          
          <Route path="/history" element={<History />} />
          
          <Route 
            path="/result" 
            element={<Result result={classificationResult} image={capturedImage} />} 
          />
        </Routes>
      </HashRouter>
    </div>
  );
}

export default App;